"""__TITLE__: minimal web MVP generated by HackAgent."""
from __future__ import annotations

from flask import Flask, jsonify, render_template, request

from core import Store

app = Flask(__name__)
store = Store()


@app.get("/")
def index():
    return render_template("index.html", items=store.items)


@app.get("/health")
def health():
    return {"status": "ok"}


@app.post("/api/items")
def add_item():
    text = (request.get_json(silent=True) or {}).get("text") or request.form.get("text", "")
    if not text.strip():
        return jsonify(error="text is required"), 400
    return jsonify(store.add(text)), 201


@app.get("/api/items")
def list_items():
    return jsonify(store.items)


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
